{
  "case_id": "xsu_sg_011_doctor_certificate",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner ikke, at UDK kan indhente lægeattest fra den praktiserende læge, som er rubrikkens kerne. I stedet hævder det, at UDK kan 'kræve' en funktionel vurdering og anmode om speciallægevurderinger og hospitalsjournaler, hvilket ikke har støtte i materialet. Attestindholdet er delvist forkert: det fremhæver diagnose, prognose og generel dagligdagsfunktion, men ikke behov for fortsat behandling eller henvisning til specialist."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Element 1 (indhente lægeattest fra den praktiserende læge) mangler. Svaret taler om 'yderligere lægeerklæringer' og specialistvurderinger, ikke egen læge. Element 2 (funktionsevne i forhold til den ansøgte funktionsnedsættelse) er kun generelt dækket som daglige aktiviteter. Element 3 (behov for fortsat behandling eller henvisning til specialist) mangler. 'Behandling og prognose' er ikke det samme."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad UDK kan gøre, og hvad lægeattesten skal beskrive. Indholdet er delvist upræcist, men det erstatter ikke svaret med irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lov, bekendtgørelse, vejledning eller afsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderbyggede regler: at UDK kan 'kræve' en funktionel vurdering, at der kan anmodes om specialistvurderinger, skemaer over medicin og hospitalsjournaler, og at attesten 'typisk' skal indeholde diagnose, prognose, kommunikation og evne til at deltage i uddannelse eller arbejde. Intet af dette fremgår af materialet. Vejledningen nævner kun attest fra praktiserende læge og i særlige tilfælde yderligere journaloplysninger."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bruger 'kan' om UDK's muligheder, men overser, at attestindhentning kræver, at funktionsniveauet ikke kan vurderes ud fra den indsendte dokumentation. Det nævner heller ikke, at journaloplysninger kun kan indhentes i særlige tilfælde. Fremmødeforbehold er ikke krævet, da fremmøde ikke omtales, men begrænsningen til særlige tilfælde mangler."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: utilstrækkelig dokumentation kan føre til krav om flere oplysninger, og attesten skal beskrive helbred og funktionsniveau. Konklusionen følger af de trin, svaret selv anfører, selv om indholdet er upræcist."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret siger, at UDK kan 'kræve' en funktionel vurdering, og at attesten 'skal' beskrive diagnose, prognose og andet. Det omdanner en skønsmæssig mulighed og et kildebaseret krav om funktionsevne og behandlingsbehov til et bredere, ikke-understøttet krav."
    }
  },
  "xhaile_coverage": {
    "A61": {
      "label": "partial",
      "reason": "Svaret siger, at UDK kan indhente yderligere oplysninger og lægeattester, men ikke at attesten kommer fra den praktiserende læge. Det dækker ikke attestens kerneindhold om funktionsevne i forhold til den søgte funktionsnedsættelse og behov for fortsat behandling eller specialisthenvisning, og nævner ikke fremmøde, journaloplysninger eller udgifter."
    }
  },
  "overall_notes": "Svaret rammer kun det generelle, at UDK kan indhente mere dokumentation. Det mangler to af tre kritiske elementer: praktiserende læge og behov for behandling eller henvisning. Desuden tilføjer det flere ukildebaserede krav, og der er ingen kildeangivelse."
}

